#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXHW 2505
#define MOD 1000000007

int H, W, N;
int black[MAXHW]; // black[i*W+j] = 1 if black
int dist[MAXHW];
int queue[MAXHW];

int dx[] = {0,0,1,-1};
int dy[] = {1,-1,0,0};

int main(){
    scanf("%d %d %d", &H, &W, &N);
    memset(black, 0, sizeof(black));
    for(int i=0;i<N;i++){
        int x,y;
        scanf("%d %d",&x,&y);
        black[x*W+y]=1;
    }

    long long ans = 0;
    int total = H*W;

    for(int s=0; s<total; s++){
        int sx = s/W, sy = s%W;
        if(black[s]) continue;

        // BFS from s
        memset(dist, -1, sizeof(int)*total);
        dist[s] = 0;
        int head=0, tail=0;
        queue[tail++] = s;

        while(head < tail){
            int cur = queue[head++];
            int cx = cur/W, cy = cur%W;
            for(int d=0;d<4;d++){
                int nx = cx+dx[d], ny = cy+dy[d];
                if(nx<0||nx>=H||ny<0||ny>=W) continue;
                int nid = nx*W+ny;
                if(black[nid]) continue;
                if(dist[nid]!=-1) continue;
                dist[nid] = dist[cur]+1;
                queue[tail++] = nid;
            }
        }

        // sum distances to all white squares with index > s (to avoid double counting)
        for(int t=s+1; t<total; t++){
            if(black[t]) continue;
            if(dist[t]==-1) continue; // unreachable - problem says "shortest distance" so maybe they're always connected?
            ans = (ans + dist[t]) % MOD;
        }
    }

    printf("%lld\n", ans);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007

typedef long long ll;

int cmp(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

int main() {
    int H, W, N;
    scanf("%d %d %d", &H, &W, &N);

    int *bx = malloc(N * sizeof(int));
    int *by = malloc(N * sizeof(int));

    for (int i = 0; i < N; i++) {
        scanf("%d %d", &bx[i], &by[i]);
    }

    ll total_white = (ll)H * W - N;
    total_white %= MOD;

    // Compute sum of x coordinates for all white cells
    // Sum all x from 0..H-1, each repeated W times
    ll sum_all_x = (ll)W * ((ll)(H-1) * H / 2 % MOD) % MOD;
    ll sum_black_x = 0;
    for (int i = 0; i < N; i++) {
        sum_black_x = (sum_black_x + bx[i]) % MOD;
    }
    ll sum_white_x = (sum_all_x - sum_black_x + MOD) % MOD;

    // Same for y
    ll sum_all_y = (ll)H * ((ll)(W-1) * W / 2 % MOD) % MOD;
    ll sum_black_y = 0;
    for (int i = 0; i < N; i++) {
        sum_black_y = (sum_black_y + by[i]) % MOD;
    }
    ll sum_white_y = (sum_all_y - sum_black_y + MOD) % MOD;

    // For x contribution, we need sorted x values of white cells.
    // We can get them by taking all x from 0..H-1 each repeated W times,
    // removing black ones. Since H, W can be large, we must compute
    // prefix sums efficiently.

    // We'll use a counting approach: 
    // For each x, count how many white cells have that x.
    // Then the contribution formula uses sum of white x and count.

    // Count of white cells per x coordinate
    // We can sort black x's and process intervals.
    qsort(bx, N, sizeof(int), cmp);

    ll res = 0;
    ll prefix_sum = 0;
    ll prefix_cnt = 0;
    int idx = 0;

    for (int x = 0; x < H; x++) {
        ll cnt = W;
        // subtract black cells in this row
        while (idx < N && bx[idx] == x) {
            cnt--;
            idx++;
        }
        if (cnt > 0) {
            // contribution from this x: 
            // x appears cnt times, each contributes to pairs:
            // coefficient = 2*prefix_cnt + cnt - 1
            // Actually formula: for each new element x repeated cnt times:
            // sum over all existing: cnt * ( sum_existing - prefix_cnt * x )? 
            // Better: use cumulative formula:
            // adding cnt copies of x adds to total:
            // cnt * (cnt * x * (prefix_cnt)??)
            // We'll compute incremental:
            ll add = (cnt * ((prefix_cnt * x) % MOD - prefix_sum + MOD)) % MOD;
            // plus pairs among these cnt copies: cnt*(cnt-1)/2 * 0? Actually same x => distance 0.
            // So only cross pairs with previous distinct x matter.
            res = (res + add) % MOD;

            // Also internal pairs among these cnt copies: distance 0, ignore.

            // Update prefix sums
            prefix_sum = (prefix_sum + (cnt * x) % MOD) % MOD;
            prefix_cnt = (prefix_cnt + cnt) % MOD;
        }
    }

    // Now same for y
    qsort(by, N, sizeof(int), cmp);
    ll res_y = 0;
    prefix_sum = 0;
    prefix_cnt = 0;
    idx = 0;

    for (int y = 0; y < W; y++) {
        ll cnt = H;
        while (idx < N && by[idx] == y) {
            cnt--;
            idx++;
        }
        if (cnt > 0) {
            ll add = (cnt * ((prefix_cnt * y) % MOD - prefix_sum + MOD)) % MOD;
            res_y = (res_y + add) % MOD;
            prefix_sum = (prefix_sum + (cnt * y) % MOD) % MOD;
            prefix_cnt = (prefix_cnt + cnt) % MOD;
        }
    }

    ll ans = (res + res_y) % MOD;
    printf("%lld\n", ans);

    free(bx);
    free(by);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MOD 1000000007LL

typedef long long ll;

typedef struct {
    int x, y;
} Point;

static int cmp_point(const void *a, const void *b) {
    const Point *p = (const Point *)a;
    const Point *q = (const Point *)b;
    if (p->x != q->x) return (p->x < q->x) ? -1 : 1;
    if (p->y != q->y) return (p->y < q->y) ? -1 : 1;
    return 0;
}

static ll mod_pow(ll a, ll e) {
    ll r = 1 % MOD;
    a %= MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    ll H, W;
    int N;
    if (scanf("%lld %lld %d", &H, &W, &N) != 3) return 0;

    Point *blk = (Point *)malloc(sizeof(Point) * (N > 0 ? N : 1));
    for (int i = 0; i < N; i++) {
        scanf("%d %d", &blk[i].x, &blk[i].y);
    }

    qsort(blk, N, sizeof(Point), cmp_point);

    /* Compress rows/cols that matter: black rows/cols and their neighbors. */
    char *row_mark = (char *)calloc((size_t)H, 1);
    char *col_mark = (char *)calloc((size_t)W, 1);

    for (int i = 0; i < N; i++) {
        int x = blk[i].x, y = blk[i].y;
        if (0 <= x && x < H) row_mark[x] = 1;
        if (x - 1 >= 0) row_mark[x - 1] = 1;
        if (x + 1 < H) row_mark[x + 1] = 1;
        if (0 <= y && y < W) col_mark[y] = 1;
        if (y - 1 >= 0) col_mark[y - 1] = 1;
        if (y + 1 < W) col_mark[y + 1] = 1;
    }

    int *rows = (int *)malloc(sizeof(int) * (H > 0 ? H : 1));
    int *cols = (int *)malloc(sizeof(int) * (W > 0 ? W : 1));
    int R = 0, C = 0;
    for (int i = 0; i < H; i++) if (row_mark[i]) rows[R++] = i;
    for (int j = 0; j < W; j++) if (col_mark[j]) cols[C++] = j;

    /* If no important rows/cols, whole grid is one white rectangle. */
    if (R == 0 || C == 0) {
        ll M = (H % MOD) * (W % MOD) % MOD;
        ll inv2 = (MOD + 1) / 2;

        ll sH = (H % MOD) * ((H - 1) % MOD) % MOD * ((H + 1) % MOD) % MOD * inv2 % MOD * mod_pow(3, MOD - 2) % MOD;
        ll sW = (W % MOD) * ((W - 1) % MOD) % MOD * ((W + 1) % MOD) % MOD * inv2 % MOD * mod_pow(3, MOD - 2) % MOD;

        ll ans = ( (W % MOD) * (W % MOD) % MOD * sH + (H % MOD) * (H % MOD) % MOD * sW ) % MOD;
        printf("%lld\n", ans);
        free(blk); free(row_mark); free(col_mark); free(rows); free(cols);
        return 0;
    }

    /* Build compressed segments */
    int SR = 2 * R + 1;
    int SC = 2 * C + 1;

    ll *rlen = (ll *)malloc(sizeof(ll) * SR);
    ll *clen = (ll *)malloc(sizeof(ll) * SC);

    for (int i = 0; i < SR; i++) rlen[i] = 0;
    for (int j = 0; j < SC; j++) clen[j] = 0;

    for (int i = 0; i < R; i++) {
        rlen[2 * i + 1] = 1;
    }
    for (int j = 0; j < C; j++) {
        clen[2 * j + 1] = 1;
    }

    rlen[0] = rows[0];
    for (int i = 0; i + 1 < R; i++) rlen[2 * i + 2] = (ll)rows[i + 1] - rows[i] - 1;
    rlen[SR - 1] = (ll)H - 1 - rows[R - 1];

    clen[0] = cols[0];
    for (int j = 0; j + 1 < C; j++) clen[2 * j + 2] = (ll)cols[j + 1] - cols[j] - 1;
    clen[SC - 1] = (ll)W - 1 - cols[C - 1];

    /* Cell blocked? only possible on odd,odd positions corresponding to exact black cells */
    char *blocked = (char *)calloc((size_t)SR * SC, 1);

    int *row_pos = (int *)malloc(sizeof(int) * H);
    int *col_pos = (int *)malloc(sizeof(int) * W);
    for (int i = 0; i < H; i++) row_pos[i] = -1;
    for (int j = 0; j < W; j++) col_pos[j] = -1;
    for (int i = 0; i < R; i++) row_pos[rows[i]] = 2 * i + 1;
    for (int j = 0; j < C; j++) col_pos[cols[j]] = 2 * j + 1;

    for (int i = 0; i < N; i++) {
        int rx = row_pos[blk[i].x];
        int cy = col_pos[blk[i].y];
        if (rx >= 0 && cy >= 0) blocked[(size_t)rx * SC + cy] = 1;
    }

    /* Assign component ids on compressed white cells */
    int total = SR * SC;
    int *comp = (int *)malloc(sizeof(int) * total);
    for (int i = 0; i < total; i++) comp[i] = -1;

    int *qx = (int *)malloc(sizeof(int) * total);
    int *qy = (int *)malloc(sizeof(int) * total);

    int comp_cnt = 0;
    ll *comp_weight = (ll *)malloc(sizeof(ll) * total);

    int dx[4] = {-1, 1, 0, 0};
    int dy[4] = {0, 0, -1, 1};

    for (int i = 0; i < SR; i++) {
        if (rlen[i] == 0) continue;
        for (int j = 0; j < SC; j++) {
            if (clen[j] == 0) continue;
            int id = i * SC + j;
            if (blocked[id] || comp[id] != -1) continue;

            int head = 0, tail = 0;
            qx[tail] = i; qy[tail] = j; tail++;
            comp[id] = comp_cnt;
            ll wsum = 0;

            while (head < tail) {
                int x = qx[head], y = qy[head]; head++;
                wsum += rlen[x] * clen[y];

                for (int d = 0; d < 4; d++) {
                    int nx = x + dx[d], ny = y + dy[d];
                    if (nx < 0 || nx >= SR || ny < 0 || ny >= SC) continue;
                    if (rlen[nx] == 0 || clen[ny] == 0) continue;
                    int nid = nx * SC + ny;
                    if (blocked[nid] || comp[nid] != -1) continue;
                    comp[nid] = comp_cnt;
                    qx[tail] = nx; qy[tail] = ny; tail++;
                }
            }
            comp_weight[comp_cnt++] = wsum % MOD;
        }
    }

    /* Build tree edges between components through each black cell.
       In a grid graph with deleted vertices, block-cut style dual here becomes a tree locally in compressed graph.
       We create unique adjacency between neighboring components around black cells. */
    int maxEdges = N * 12 + 10;
    int *eu = (int *)malloc(sizeof(int) * maxEdges);
    int *ev = (int *)malloc(sizeof(int) * maxEdges);
    int E = 0;

    for (int k = 0; k < N; k++) {
        int x = row_pos[blk[k].x];
        int y = col_pos[blk[k].y];
        int neigh[4], m = 0;

        if (x > 0) {
            int id = (x - 1) * SC + y;
            if (rlen[x - 1] && clen[y] && !blocked[id]) neigh[m++] = comp[id];
        }
        if (x + 1 < SR) {
            int id = (x + 1) * SC + y;
            if (rlen[x + 1] && clen[y] && !blocked[id]) neigh[m++] = comp[id];
        }
        if (y > 0) {
            int id = x * SC + (y - 1);
            if (rlen[x] && clen[y - 1] && !blocked[id]) neigh[m++] = comp[id];
        }
        if (y + 1 < SC) {
            int id = x * SC + (y + 1);
            if (rlen[x] && clen[y + 1] && !blocked[id]) neigh[m++] = comp[id];
        }

        for (int a = 0; a < m; a++) {
            for (int b = a + 1; b < m; b++) {
                if (neigh[a] == neigh[b]) continue;
                if (E < maxEdges) {
                    eu[E] = neigh[a];
                    ev[E] = neigh[b];
                    E++;
                }
            }
        }
    }

    /* Deduplicate edges */
    if (E > 0) {
        ll *keys = (ll *)malloc(sizeof(ll) * E);
        for (int i = 0; i < E; i++) {
            int a = eu[i], b = ev[i];
            if (a > b) { int t = a; a = b; b = t; }
            keys[i] = (ll)a * comp_cnt + b;
        }
        int cmp_ll(const void *a, const void *b) {
            ll x = *(const ll *)a, y = *(const ll *)b;
            return (x < y) ? -1 : (x > y);
        }
        qsort(keys, E, sizeof(ll), cmp_ll);

        int ne = 0;
        for (int i = 0; i < E; i++) {
            if (i == 0 || keys[i] != keys[i - 1]) {
                eu[ne] = (int)(keys[i] / comp_cnt);
                ev[ne] = (int)(keys[i] % comp_cnt);
                ne++;
            }
        }
        E = ne;
        free(keys);
    }

    /* adjacency */
    int *deg = (int *)calloc(comp_cnt, sizeof(int));
    for (int i = 0; i < E; i++) {
        deg[eu[i]]++;
        deg[ev[i]]++;
    }
    int *ofs = (int *)malloc(sizeof(int) * (comp_cnt + 1));
    ofs[0] = 0;
    for (int i = 0; i < comp_cnt; i++) ofs[i + 1] = ofs[i] + deg[i];
    int *adj = (int *)malloc(sizeof(int) * (ofs[comp_cnt] > 0 ? ofs[comp_cnt] : 1));
    int *cur = (int *)calloc(comp_cnt, sizeof(int));
    for (int i = 0; i < E; i++) {
        int a = eu[i], b = ev[i];
        adj[ofs[a] + cur[a]++] = b;
        adj[ofs[b] + cur[b]++] = a;
    }

    /* Sum pair distances between components in the tree/forest:
       each edge contributes s*(T-s), where s is subtree white-cell count. */
    ll totalWhite = 0;
    for (int i = 0; i < comp_cnt; i++) totalWhite = (totalWhite + comp_weight[i]) % MOD;

    int *parent = (int *)malloc(sizeof(int) * comp_cnt);
    int *order = (int *)malloc(sizeof(int) * comp_cnt);
    char *vis = (char *)calloc(comp_cnt, 1);
    ll *sub = (ll *)malloc(sizeof(ll) * comp_cnt);

    ll ans = 0;

    for (int root = 0; root < comp_cnt; root++) {
        if (vis[root]) continue;
        int top = 0, ordn = 0;
        order[top++] = root;
        parent[root] = -1;
        vis[root] = 1;

        for (int p = 0; p < top; p++) {
            int v = order[p];
            ordn++;
            for (int it = ofs[v]; it < ofs[v + 1]; it++) {
                int to = adj[it];
                if (to == parent[v]) continue;
                if (vis[to]) continue;
                vis[to] = 1;
                parent[to] = v;
                order[top++] = to;
            }
        }

        for (int i = ordn - 1; i >= 0; i--) {
            int v = order[i];
            sub[v] = comp_weight[v] % MOD;
            for (int it = ofs[v]; it < ofs[v + 1]; it++) {
                int to = adj[it];
                if (parent[to] == v) {
                    sub[v] += sub[to];
                    if (sub[v] >= MOD) sub[v] -= MOD;
                }
            }
        }

        for (int i = 1; i < ordn; i++) {
            int v = order[i];
            ll s = sub[v];
            ll t = (totalWhite - s + MOD) % MOD;
            ans = (ans + s * t) % MOD;
        }
    }

    printf("%lld\n", ans % MOD);

    free(blk);
    free(row_mark); free(col_mark);
    free(rows); free(cols);
    free(rlen); free(clen);
    free(blocked);
    free(row_pos); free(col_pos);
    free(comp);
    free(qx); free(qy);
    free(comp_weight);
    free(eu); free(ev);
    free(deg); free(ofs); free(adj); free(cur);
    free(parent); free(order); free(vis); free(sub);

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MOD = 1e9 + 7;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int H, W, N;
    cin >> H >> W >> N;

    vector<vector<bool>> black(H, vector<bool>(W, false));
    for (int i = 0; i < N; i++) {
        int x, y;
        cin >> x >> y;
        black[x][y] = true;
    }

    vector<pair<int,int>> whites;
    for (int i = 0; i < H; i++)
        for (int j = 0; j < W; j++)
            if (!black[i][j])
                whites.push_back({i, j});

    int dx[] = {0,0,1,-1};
    int dy[] = {1,-1,0,0};

    long long ans = 0;

    for (auto [sr, sc] : whites) {
        vector<vector<int>> dist(H, vector<int>(W, -1));
        queue<pair<int,int>> q;
        dist[sr][sc] = 0;
        q.push({sr, sc});
        while (!q.empty()) {
            auto [r, c] = q.front(); q.pop();
            for (int d = 0; d < 4; d++) {
                int nr = r + dx[d], nc = c + dy[d];
                if (nr >= 0 && nr < H && nc >= 0 && nc < W && !black[nr][nc] && dist[nr][nc] == -1) {
                    dist[nr][nc] = dist[r][c] + 1;
                    q.push({nr, nc});
                }
            }
        }
        for (auto [er, ec] : whites) {
            if (dist[er][ec] > 0) {
                ans = (ans + dist[er][ec]) % MOD;
            }
        }
    }

    // Each pair counted twice
    ans = (ans / 2) % MOD; // This division is wrong with modular arithmetic
    // Actually ans is already sum of all ordered pairs, divide by 2
    // Since ans is even before mod, we need to be careful
    // Let's accumulate without mod first, or use modular inverse of 2

    // Redo: accumulate full value then divide (but might overflow)
    // Better: since we count each pair twice, just divide by 2 at the end
    // ans here is sum of all ordered pairs (each unordered pair counted twice)
    // Use modular inverse of 2
    long long inv2 = (MOD + 1) / 2; // since MOD is odd prime, inv2 = (MOD+1)/2
    ans = ans % MOD * inv2 % MOD;

    cout << ans << endl;
    return 0;
}

