using int64 = long long;
const int MOD = 1e9 + 7;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W, N;
    cin >> H >> W >> N;

    vector<int> xs(N), ys(N);
    for (int i = 0; i < N; i++) {
        int x, y;
        cin >> x >> y;
        xs[i] = x;
        ys[i] = y;
    }

    // Total white cells = H*W - N
    int64 white = (int64)H * W - N;
    white %= MOD;

    // Collect coordinates of white cells
    vector<int> white_x, white_y;

    // Mark black cells
    set<pair<int,int>> black;
    for (int i = 0; i < N; i++) {
        black.insert({xs[i], ys[i]});
    }

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (black.find({i, j}) == black.end()) {
                white_x.push_back(i);
                white_y.push_back(j);
            }
        }
    }

    sort(white_x.begin(), white_x.end());
    sort(white_y.begin(), white_y.end());

    int64 sum_x = 0, prefix_x = 0;
    for (size_t i = 0; i < white_x.size(); i++) {
        sum_x = (sum_x + (int64)white_x[i] * i - prefix_x) % MOD;
        prefix_x = (prefix_x + white_x[i]) % MOD;
    }

    int64 sum_y = 0, prefix_y = 0;
    for (size_t i = 0; i < white_y.size(); i++) {
        sum_y = (sum_y + (int64)white_y[i] * i - prefix_y) % MOD;
        prefix_y = (prefix_y + white_y[i]) % MOD;
    }

    int64 ans = (sum_x + sum_y) % MOD;
    if (ans < 0) ans += MOD;
    cout << ans << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long H, W;
    int N;
    cin >> H >> W >> N;

    vector<pair<long long,long long>> black(N);
    for (int i = 0; i < N; ++i) {
        cin >> black[i].first >> black[i].second;
    }

    // Compress rows/cols containing black cells.
    vector<long long> xs, ys;
    xs.reserve(N);
    ys.reserve(N);
    for (auto &p : black) {
        xs.push_back(p.first);
        ys.push_back(p.second);
    }
    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());
    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());

    int R = (int)xs.size();
    int C = (int)ys.size();

    unordered_map<long long,int> xid, yid;
    xid.reserve(R * 2 + 1);
    yid.reserve(C * 2 + 1);
    for (int i = 0; i < R; ++i) xid[xs[i]] = i;
    for (int j = 0; j < C; ++j) yid[ys[j]] = j;

    vector<vector<int>> blocked(R, vector<int>(C, 0));
    for (auto &p : black) {
        blocked[xid[p.first]][yid[p.second]] = 1;
    }

    // Row groups: consecutive rows with same black pattern.
    vector<long long> rowLen;
    vector<vector<int>> rowBlocks; // blocked column ids in this row-group pattern
    {
        vector<vector<int>> rowPat(R);
        for (int i = 0; i < R; ++i) {
            for (int j = 0; j < C; ++j) if (blocked[i][j]) rowPat[i].push_back(j);
        }

        long long prev = 0;
        int i = 0;
        while (i < R) {
            if (prev < xs[i]) {
                rowLen.push_back(xs[i] - prev);
                rowBlocks.push_back({});
            }
            int j = i;
            while (j + 1 < R && rowPat[j + 1] == rowPat[i] && xs[j + 1] == xs[j] + 1) ++j;
            rowLen.push_back(xs[j] - xs[i] + 1);
            rowBlocks.push_back(rowPat[i]);
            prev = xs[j] + 1;
            i = j + 1;
        }
        if (prev < H) {
            rowLen.push_back(H - prev);
            rowBlocks.push_back({});
        }
    }

    // Column groups: consecutive cols with same black pattern.
    vector<long long> colLen;
    vector<vector<int>> colBlocks; // blocked row ids in this col-group pattern
    {
        vector<vector<int>> colPat(C);
        for (int j = 0; j < C; ++j) {
            for (int i = 0; i < R; ++i) if (blocked[i][j]) colPat[j].push_back(i);
        }

        long long prev = 0;
        int j = 0;
        while (j < C) {
            if (prev < ys[j]) {
                colLen.push_back(ys[j] - prev);
                colBlocks.push_back({});
            }
            int k = j;
            while (k + 1 < C && colPat[k + 1] == colPat[j] && ys[k + 1] == ys[k] + 1) ++k;
            colLen.push_back(ys[k] - ys[j] + 1);
            colBlocks.push_back(colPat[j]);
            prev = ys[k] + 1;
            j = k + 1;
        }
        if (prev < W) {
            colLen.push_back(W - prev);
            colBlocks.push_back({});
        }
    }

    int RG = (int)rowLen.size();
    int CG = (int)colLen.size();

    // Build white rectangles = row-group x column-group except blocked singleton black cells.
    // Since inside each group pair, either all white or exactly one black cell can appear.
    vector<long long> rectW;
    vector<long long> rectH;
    vector<long long> rectCnt;
    vector<int> rectRow, rectCol;
    vector<vector<int>> id(RG, vector<int>(CG, -1));

    for (int i = 0; i < RG; ++i) {
        unordered_set<int> s(rowBlocks[i].begin(), rowBlocks[i].end());
        for (int j = 0; j < CG; ++j) {
            bool hasBlack = false;
            if (!rowBlocks[i].empty() && !colBlocks[j].empty()) {
                // possible only if both are singleton corresponding to exact black point
                // check intersection existence
                for (int c : rowBlocks[i]) {
                    if (find(colBlocks[j].begin(), colBlocks[j].end(), c) != colBlocks[j].end()) {
                        hasBlack = true;
                        break;
                    }
                }
            }
            long long cells = rowLen[i] * colLen[j] - (hasBlack ? 1LL : 0LL);
            if (cells > 0) {
                int idx = (int)rectCnt.size();
                id[i][j] = idx;
                rectW.push_back(colLen[j]);
                rectH.push_back(rowLen[i]);
                rectCnt.push_back(cells % MOD);
                rectRow.push_back(i);
                rectCol.push_back(j);
            }
        }
    }

    int M = (int)rectCnt.size();

    // Graph of adjacent white rectangles.
    vector<vector<int>> g(M);
    for (int i = 0; i < RG; ++i) {
        for (int j = 0; j < CG; ++j) if (id[i][j] != -1) {
            int u = id[i][j];
            if (i + 1 < RG && id[i + 1][j] != -1) {
                int v = id[i + 1][j];
                g[u].push_back(v);
                g[v].push_back(u);
            }
            if (j + 1 < CG && id[i][j + 1] != -1) {
                int v = id[i][j + 1];
                g[u].push_back(v);
                g[v].push_back(u);
            }
        }
    }

    // Total answer:
    // sum over all unordered white cell pairs Manhattan distance in obstacle-free compressed regions.
    // Because black cells are points, shortest path in white cells equals Manhattan distance
    // whenever connected through adjacent white rectangles in this partition.
    //
    // We compute:
    // 1) contribution of row differences among all white cells
    // 2) contribution of col differences among all white cells
    //
    // Since removing points does not affect separability except connectivity across exact blocked cells,
    // and graph handles this by components. For each connected component, sum pairwise |x1-x2|+|y1-y2|.
    //
    // Collect intervals in each component by DFS on rectangle graph.

    vector<int> comp(M, -1);
    int comps = 0;
    for (int i = 0; i < M; ++i) if (comp[i] == -1) {
        queue<int> q;
        q.push(i);
        comp[i] = comps;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : g[u]) if (comp[v] == -1) {
                comp[v] = comps;
                q.push(v);
            }
        }
        comps++;
    }

    vector<vector<int>> byComp(comps);
    for (int i = 0; i < M; ++i) byComp[comp[i]].push_back(i);

    auto sum1DIntervals = [&](vector<tuple<long long,long long,long long>> segs)->long long {
        // Each segment [l, r] with multiplicity mult per point.
        // Sum over unordered pairs of points from all segments: |a-b| * mult_a * mult_b
        // Works by sweep on coordinates because segments are disjoint in compressed partition usage.
        sort(segs.begin(), segs.end());
        long long ans = 0;
        long long prefCnt = 0, prefSum = 0; // weighted count, weighted coord sum
        for (auto &[l, r, mult] : segs) {
            long long len = r - l + 1;
            long long cnt = (len % MOD) * (mult % MOD) % MOD;
            long long sumCoords = (( (l + r) % MOD ) * (len % MOD) % MOD * ((MOD + 1) / 2)) % MOD;
            sumCoords = sumCoords * (mult % MOD) % MOD;

            ans = (ans + cnt * prefSum % MOD - sumCoords * prefCnt % MOD + MOD) % MOD;

            prefCnt = (prefCnt + cnt) % MOD;
            prefSum = (prefSum + sumCoords) % MOD;
        }
        return ans;
    };

    long long answer = 0;

    for (int cc = 0; cc < comps; ++cc) {
        vector<tuple<long long,long long,long long>> rowSegs, colSegs;
        rowSegs.reserve(byComp[cc].size());
        colSegs.reserve(byComp[cc].size());

        // Need actual coordinate ranges of row/col groups.
        vector<long long> rowStart(RG), colStart(CG);
        {
            long long cur = 0;
            for (int i = 0; i < RG; ++i) {
                rowStart[i] = cur;
                cur += rowLen[i];
            }
            cur = 0;
            for (int j = 0; j < CG; ++j) {
                colStart[j] = cur;
                cur += colLen[j];
            }
        }

        for (int idx : byComp[cc]) {
            int i = rectRow[idx], j = rectCol[idx];
            long long rs = rowStart[i], re = rs + rowLen[i] - 1;
            long long cs = colStart[j], ce = cs + colLen[j] - 1;

            // For row contribution: each row point in this interval repeated by width count,
            // except if this rectangle is a single black-removed cell, then one row and one col lose 1 point.
            // But in our construction cells count only stored total, not exact per-row/per-col deficiency.
            // Since only possible deficiency is one exact point, handle it explicitly.
            bool deficient = (rowLen[i] * colLen[j] - 1 == (long long)(rectCnt[idx] % MOD == (rowLen[i]*colLen[j]-1)%MOD ? rowLen[i]*colLen[j]-1 : -2)
                              && rowLen[i] * colLen[j] >= 1 && rectCnt[idx] == (rowLen[i] * colLen[j] - 1) % MOD);

            // Safer detection:
            long long full = rowLen[i] * colLen[j];
            bool minusOne = false;
            if (full > 0) {
                long long stored = rectCnt[idx];
                if (stored == (full - 1) % MOD && full - 1 >= 0) {
                    // distinguish from full % MOD collision unlikely but possible; use pattern intersection
                    minusOne = false;
                    if (!rowBlocks[i].empty() && !colBlocks[j].empty()) {
                        for (int c : rowBlocks[i]) {
                            if (find(colBlocks[j].begin(), colBlocks[j].end(), c) != colBlocks[j].end()) {
                                minusOne = true;
                                break;
                            }
                        }
                    }
                }
            }

            if (!minusOne) {
                rowSegs.emplace_back(rs, re, colLen[j] % MOD);
                colSegs.emplace_back(cs, ce, rowLen[i] % MOD);
            } else {
                // Determine exact missing row/col: singleton black point.
                int br = colBlocks[j][0];
                int bc = rowBlocks[i][0];
                long long missR = xs[br];
                long long missC = ys[bc];

                if (rs <= missR - 1)
                    rowSegs.emplace_back(rs, missR - 1, colLen[j] % MOD);
                rowSegs.emplace_back(missR, missR, (colLen[j] - 1) % MOD);
                if (missR + 1 <= re)
                    rowSegs.emplace_back(missR + 1, re, colLen[j] % MOD);

                if (cs <= missC - 1)
                    colSegs.emplace_back(cs, missC - 1, rowLen[i] % MOD);
                colSegs.emplace_back(missC, missC, (rowLen[i] - 1) % MOD);
                if (missC + 1 <= ce)
                    colSegs.emplace_back(missC + 1, ce, rowLen[i] % MOD);
            }
        }

        answer = (answer + sum1DIntervals(rowSegs)) % MOD;
        answer = (answer + sum1DIntervals(colSegs)) % MOD;
    }

    cout << answer % MOD << '\n';
    return 0;
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int H = sc.nextInt(), W = sc.nextInt(), N = sc.nextInt();
        boolean[][] black = new boolean[H][W];
        for (int i = 0; i < N; i++) {
            int x = sc.nextInt(), y = sc.nextInt();
            black[x][y] = true;
        }

        long MOD = 1_000_000_007L;
        long ans = 0;
        int[] dx = {0,0,1,-1};
        int[] dy = {1,-1,0,0};

        // BFS from each white square
        int[][] dist = new int[H][W];

        for (int si = 0; si < H; si++) {
            for (int sj = 0; sj < W; sj++) {
                if (black[si][sj]) continue;
                // BFS
                for (int[] row : dist) Arrays.fill(row, -1);
                dist[si][sj] = 0;
                Queue<int[]> q = new ArrayDeque<>();
                q.add(new int[]{si, sj});
                while (!q.isEmpty()) {
                    int[] cur = q.poll();
                    int cx = cur[0], cy = cur[1];
                    for (int d = 0; d < 4; d++) {
                        int nx = cx + dx[d];
                        int ny = cy + dy[d];
                        if (nx >= 0 && nx < H && ny >= 0 && ny < W && !black[nx][ny] && dist[nx][ny] == -1) {
                            dist[nx][ny] = dist[cx][cy] + 1;
                            q.add(new int[]{nx, ny});
                        }
                    }
                }
                // Sum distances to all white squares with index > (si,sj) to avoid double counting
                for (int ti = 0; ti < H; ti++) {
                    for (int tj = 0; tj < W; tj++) {
                        if (black[ti][tj]) continue;
                        if (ti * W + tj <= si * W + sj) continue;
                        if (dist[ti][tj] >= 0) {
                            ans = (ans + dist[ti][tj]) % MOD;
                        }
                    }
                }
            }
        }

        System.out.println(ans);
    }
}

import java.io.*;
import java.util.*;

public class Solution {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int H = Integer.parseInt(st.nextToken());
        int W = Integer.parseInt(st.nextToken());
        int N = Integer.parseInt(st.nextToken());

        Map<Integer, Integer> rowBlack = new HashMap<>();
        Map<Integer, Integer> colBlack = new HashMap<>();

        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(st.nextToken());
            int y = Integer.parseInt(st.nextToken());
            rowBlack.put(x, rowBlack.getOrDefault(x, 0) + 1);
            colBlack.put(y, colBlack.getOrDefault(y, 0) + 1);
        }

        long totalWhite = (long) H * W - N;
        long ans = 0;

        // --- x contributions ---
        List<Integer> rows = new ArrayList<>(rowBlack.keySet());
        Collections.sort(rows);
        long seen = 0;
        int rowIdx = 0;
        for (int r = 0; r < H; r++) {
            long whiteInRow = W;
            if (rowIdx < rows.size() && rows.get(rowIdx) == r) {
                whiteInRow -= rowBlack.get(r);
                rowIdx++;
            }
            if (whiteInRow == 0) continue;
            long remaining = totalWhite - seen - whiteInRow;
            long add = (whiteInRow % MOD) * ((seen - remaining) % MOD) % MOD;
            add = (add * (r % MOD)) % MOD;
            ans = (ans + add) % MOD;
            seen += whiteInRow;
        }

        // --- y contributions ---
        List<Integer> cols = new ArrayList<>(colBlack.keySet());
        Collections.sort(cols);
        seen = 0;
        int colIdx = 0;
        for (int c = 0; c < W; c++) {
            long whiteInCol = H;
            if (colIdx < cols.size() && cols.get(colIdx) == c) {
                whiteInCol -= colBlack.get(c);
                colIdx++;
            }
            if (whiteInCol == 0) continue;
            long remaining = totalWhite - seen - whiteInCol;
            long add = (whiteInCol % MOD) * ((seen - remaining) % MOD) % MOD;
            add = (add * (c % MOD)) % MOD;
            ans = (ans + add) % MOD;
            seen += whiteInCol;
        }

        System.out.println(ans);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static long mod(long x) {
        x %= MOD;
        if (x < 0) x += MOD;
        return x;
    }

    static long sumConsecutive(long n) {
        // 1 + 2 + ... + n
        return mod(n % MOD * ((n + 1) % MOD) % MOD * inv2 % MOD);
    }

    static long sumPairs1D(long[] a) {
        // sum_{i<j} (a[j] - a[i]), a sorted
        long res = 0;
        long pref = 0;
        for (int i = 0; i < a.length; i++) {
            long ai = mod(a[i]);
            res = (res + ai * i - pref) % MOD;
            pref = (pref + ai) % MOD;
        }
        return mod(res);
    }

    static long inv2 = (MOD + 1) / 2;
    static long inv6 = 166666668L;

    static long rangeSum(long l, long r) {
        if (l > r) return 0;
        return mod(prefixSum(r) - prefixSum(l - 1));
    }

    static long prefixSum(long n) {
        if (n <= 0) return 0;
        return mod(n % MOD * ((n + 1) % MOD) % MOD * inv2 % MOD);
    }

    static long prefixSumSq(long n) {
        if (n <= 0) return 0;
        long a = n % MOD;
        long b = (n + 1) % MOD;
        long c = (2 * (n % MOD) + 1) % MOD;
        return mod(a * b % MOD * c % MOD * inv6 % MOD);
    }

    static long sumDistAllCells1D(long L) {
        // sum over all unordered pairs in [0..L-1] of distance
        // = L*(L-1)*(L+1)/6
        long lm = L % MOD;
        return mod(lm * ((L - 1) % MOD) % MOD * ((L + 1) % MOD) % MOD * inv6 % MOD);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        long H = fs.nextLong();
        long W = fs.nextLong();
        int N = fs.nextInt();

        long[] xs = new long[N];
        long[] ys = new long[N];
        HashSet<Long> blackSet = new HashSet<>(Math.max(16, N * 2));
        for (int i = 0; i < N; i++) {
            xs[i] = fs.nextLong();
            ys[i] = fs.nextLong();
            blackSet.add((xs[i] << 32) ^ ys[i]);
        }

        long totalWhite = H * W - N;

        // Total over all cells ignoring black:
        // Manhattan distances split into row and column parts.
        long total = 0;
        total = (total + sumDistAllCells1D(H) * (W % MOD)) % MOD;
        total = (total + sumDistAllCells1D(W) * (H % MOD)) % MOD;

        // Subtract distances between black and white pairs counted in total,
        // then add back black-black pairs because they were subtracted twice.
        Arrays.sort(xs);
        Arrays.sort(ys);

        long blackToAllRows = 0;
        {
            long sumBlackRows = 0;
            for (long x : xs) sumBlackRows = (sumBlackRows + x) % MOD;
            long sumAllRows = mod((W % MOD) * prefixSum(H - 1) % MOD);

            // For each black row x:
            // sum over all cells (r,c) of |x-r| = W * f(x)
            // Total over black x can be computed directly:
            // f(x)= x*(x+1)/2 + (H-1-x)*(H-x)/2
            for (long x : xs) {
                long left = mod(x % MOD * ((x + 1) % MOD) % MOD * inv2 % MOD);
                long t = H - 1 - x;
                long right = mod((t % MOD) * ((t + 1) % MOD) % MOD * inv2 % MOD);
                blackToAllRows = (blackToAllRows + (left + right) % MOD) % MOD;
            }
            blackToAllRows = blackToAllRows * (W % MOD) % MOD;
        }

        long blackToAllCols = 0;
        {
            for (long y : ys) {
                long left = mod(y % MOD * ((y + 1) % MOD) % MOD * inv2 % MOD);
                long t = W - 1 - y;
                long right = mod((t % MOD) * ((t + 1) % MOD) % MOD * inv2 % MOD);
                blackToAllCols = (blackToAllCols + (left + right) % MOD) % MOD;
            }
            blackToAllCols = blackToAllCols * (H % MOD) % MOD;
        }

        long blackToAll = (blackToAllRows + blackToAllCols) % MOD;

        // black-black unordered total
        long bb = 0;
        bb = (bb + sumPairs1D(xs)) % MOD;
        bb = (bb + sumPairs1D(ys)) % MOD;

        // black-white total = black-all - 2*black-black
        long blackWhite = mod(blackToAll - 2L * bb);

        // Result among white-white:
        // total(all-all) = ww + bw + bb
        // => ww = total - bw - bb
        long ans = mod(total - blackWhite - bb);

        System.out.println(ans);
    }
}

